def sumar_todo(*numeros):
    return sum(numeros)

def registrar_evento(evento, **metadata):
    print(f"Evento: {evento}")
    for k, v in metadata.items():
        print(f"  {k}: {v}")

print("Suma:", sumar_todo(10, 20, 30, 40))
registrar_evento("LOGIN", usuario="alex", ip="192.168.1.1", exito=True)

